//! Fixture and behavior tests for the treemap renderer.
//!
//! The fixtures in `tests/render/` are generated by
//! `research/mermaid-port/harness/generate-treemap-render-fixtures.mjs`: upstream mermaid
//! rendered under jsdom with the shared monospace measure, read back from the SVG geometry.

use serde_json::Value;

use super::*;
use crate::scene::Item;

const TOLERANCE: f64 = 0.01;

fn fixtures() -> Vec<(String, Value)> {
    let dir =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/diagrams/treemap/tests/render");
    let mut fixtures: Vec<(String, Value)> = std::fs::read_dir(&dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.extension().and_then(|extension| extension.to_str()) == Some("json"))
        .map(|path| {
            let text = std::fs::read_to_string(&path).expect("read fixture");
            let value: Value = serde_json::from_str(&text).expect("parse fixture");
            (
                path.file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default()
                    .to_string(),
                value,
            )
        })
        .collect();
    fixtures.sort_by(|a, b| a.0.cmp(&b.0));
    fixtures
}

fn close(actual: f64, expected: f64, what: &str, file: &str) {
    assert!(
        (actual - expected).abs() <= TOLERANCE,
        "{file}: {what}: actual {actual} vs expected {expected}"
    );
}

fn number(value: &Value, key: &str, file: &str) -> f64 {
    value
        .get(key)
        .and_then(Value::as_f64)
        .unwrap_or_else(|| panic!("{file}: missing number {key} in {value}"))
}

fn group<'a>(item: &'a Item, file: &str, what: &str) -> &'a Group {
    match item {
        Item::Group(group) => group,
        _ => panic!("{file}: {what} is not a group"),
    }
}

fn rect<'a>(item: &'a Item, file: &str, what: &str) -> &'a RectShape {
    match item {
        Item::Rect(rect) => rect,
        _ => panic!("{file}: {what} is not a rect"),
    }
}

fn text_of(run: &TextRun) -> String {
    run.lines
        .iter()
        .map(|line| line.text())
        .collect::<Vec<_>>()
        .join("\n")
}

fn color_of(color: &Option<Color>) -> Option<&str> {
    color.as_ref().map(|color| color.0.as_str())
}

fn expected_color(value: &Value, file: &str, what: &str) -> Option<String> {
    match value {
        Value::Null => None,
        Value::String(text) if text == "none" => None,
        Value::String(text) => Some(text.clone()),
        other => panic!("{file}: {what} is not a color: {other}"),
    }
}

fn assert_rect(actual: &RectShape, expected: &Value, file: &str, what: &str) {
    close(
        actual.rect.width,
        number(expected, "width", file),
        &format!("{what} width"),
        file,
    );
    close(
        actual.rect.height,
        number(expected, "height", file),
        &format!("{what} height"),
        file,
    );
    assert_eq!(
        color_of(&actual.style.fill),
        expected_color(&expected["fill"], file, &format!("{what} fill")).as_deref(),
        "{file}: {what} fill"
    );
    close(
        actual.style.fill_opacity,
        number(expected, "fillOpacity", file),
        &format!("{what} fill opacity"),
        file,
    );
    assert_eq!(
        color_of(&actual.style.stroke),
        expected_color(&expected["stroke"], file, &format!("{what} stroke")).as_deref(),
        "{file}: {what} stroke"
    );
    close(
        actual.style.stroke_width,
        number(expected, "strokeWidth", file),
        &format!("{what} stroke width"),
        file,
    );
    close(
        actual.style.stroke_opacity,
        number(expected, "strokeOpacity", file),
        &format!("{what} stroke opacity"),
        file,
    );
}

fn expected_text(value: &Value) -> Option<&Value> {
    match value {
        Value::Object(_) => {
            let text = value
                .get("text")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let hidden = value.get("display").and_then(Value::as_str) == Some("none");
            (!text.is_empty() && !hidden).then_some(value)
        }
        _ => None,
    }
}

fn assert_text(actual: &TextRun, expected: &Value, file: &str, what: &str) {
    assert_eq!(
        text_of(actual),
        expected["text"].as_str().expect("text"),
        "{file}: {what} text"
    );
    close(
        actual.position.x,
        number(expected, "x", file),
        &format!("{what} x"),
        file,
    );
    close(
        actual.position.y,
        number(expected, "y", file),
        &format!("{what} y"),
        file,
    );
    close(
        actual.font.size,
        number(expected, "fontSize", file),
        &format!("{what} font size"),
        file,
    );
    let expected_anchor = match expected["anchor"].as_str() {
        Some("middle") => TextAnchor::Middle,
        Some("end") => TextAnchor::End,
        _ => TextAnchor::Start,
    };
    assert_eq!(actual.anchor, expected_anchor, "{file}: {what} anchor");
    let expected_baseline = match expected["baseline"].as_str() {
        Some("middle") => TextBaseline::Middle,
        Some("hanging") => TextBaseline::Hanging,
        _ => TextBaseline::Alphabetic,
    };
    assert_eq!(
        actual.baseline, expected_baseline,
        "{file}: {what} baseline"
    );
    assert_eq!(
        color_of(&actual.fill),
        expected_color(&expected["fill"], file, &format!("{what} fill")).as_deref(),
        "{file}: {what} fill"
    );
    let expected_weight = match expected["weight"].as_str() {
        Some("bold") => 700,
        Some("normal") | None | Some("") => 400,
        Some(other) => other.parse().expect("font weight"),
    };
    assert_eq!(actual.font.weight, expected_weight, "{file}: {what} weight");
    assert_eq!(
        actual.font.italic,
        expected["italic"].as_str() == Some("italic"),
        "{file}: {what} italic"
    );
}

fn find_text(group: &Group, baseline: TextBaseline) -> Option<&TextRun> {
    group.items.iter().find_map(|item| match item {
        Item::Text(run) if run.baseline == baseline => Some(run),
        _ => None,
    })
}

fn find_section_text(group: &Group, anchor: TextAnchor) -> Option<&TextRun> {
    group.items.iter().find_map(|item| match item {
        Item::Text(run) if run.anchor == anchor => Some(run),
        _ => None,
    })
}

#[test]
fn renders_recorded_treemap_fixtures() {
    let fixtures = fixtures();
    assert!(
        fixtures.len() >= 8,
        "expected at least 8 fixtures, found {}",
        fixtures.len()
    );

    for (file, fixture) in fixtures {
        let source = fixture["source"].as_str().expect("fixture source");
        let preprocessed = crate::preprocess::preprocess(source);
        let config = Config::from_source_config(&preprocessed.config)
            .unwrap_or_else(|error| panic!("{file}: config: {error}"));
        let ast = super::super::parse(&preprocessed.body)
            .unwrap_or_else(|error| panic!("{file}: parse: {error}"));
        let scene = draw_ast(&ast, &config, &crate::measure::FallbackMeasure);
        let expected = &fixture["expected"];

        let view_box = &expected["viewBox"];
        close(
            scene.view_box.x,
            number(view_box, "x", &file),
            "viewBox x",
            &file,
        );
        close(
            scene.view_box.y,
            number(view_box, "y", &file),
            "viewBox y",
            &file,
        );
        close(
            scene.view_box.width,
            number(view_box, "width", &file),
            "viewBox width",
            &file,
        );
        close(
            scene.view_box.height,
            number(view_box, "height", &file),
            "viewBox height",
            &file,
        );

        let expected_title = expected_text(&expected["title"]);
        match expected_title {
            Some(expected_title) => {
                let title = match &scene.items[0] {
                    Item::Text(run) => run,
                    _ => panic!("{file}: title is not text"),
                };
                assert_text(title, expected_title, &file, "title");
            }
            None => assert!(
                matches!(scene.items[0], Item::Group(_)),
                "{file}: unexpected title"
            ),
        }

        let container = scene
            .items
            .iter()
            .find_map(|item| match item {
                Item::Group(group) if group.class.as_deref() == Some("treemapContainer") => {
                    Some(group)
                }
                _ => None,
            })
            .unwrap_or_else(|| panic!("{file}: missing treemapContainer"));
        close(
            container.transform.e,
            number(&expected["containerTransform"], "x", &file),
            "container x",
            &file,
        );
        close(
            container.transform.f,
            number(&expected["containerTransform"], "y", &file),
            "container y",
            &file,
        );

        let actual_sections: Vec<&Group> = container
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Group(group) if group.class.as_deref() == Some("treemapSection") => {
                    Some(group)
                }
                _ => None,
            })
            .collect();
        let expected_sections: Vec<&Value> = expected["sections"]
            .as_array()
            .expect("sections")
            .iter()
            .filter(|section| section["body"]["display"].as_str() != Some("none"))
            .collect();
        assert_eq!(
            actual_sections.len(),
            expected_sections.len(),
            "{file}: section count"
        );

        for (index, (actual, expected)) in actual_sections.iter().zip(expected_sections).enumerate()
        {
            close(
                actual.transform.e,
                number(&expected["transform"], "x", &file),
                &format!("section {index} x"),
                &file,
            );
            close(
                actual.transform.f,
                number(&expected["transform"], "y", &file),
                &format!("section {index} y"),
                &file,
            );
            let header = rect(&actual.items[0], &file, "section header");
            assert_rect(header, &expected["header"], &file, "section header");
            let body = rect(&actual.items[1], &file, "section body");
            assert_rect(
                body,
                &expected["body"],
                &file,
                &format!("section {index} body"),
            );

            let clip = actual.items.iter().find_map(|item| match item {
                Item::Group(group) => Some(group),
                _ => None,
            });
            let expected_label = expected_text(&expected["label"]);
            let expected_value = expected_text(&expected["value"]);
            match clip {
                Some(clip) => {
                    match expected_label {
                        Some(expected_label) => {
                            let label = find_section_text(clip, TextAnchor::Start)
                                .unwrap_or_else(|| panic!("{file}: missing section {index} label"));
                            assert_text(
                                label,
                                expected_label,
                                &file,
                                &format!("section {index} label"),
                            );
                        }
                        None => assert!(
                            find_section_text(clip, TextAnchor::Start).is_none(),
                            "{file}: unexpected section {index} label"
                        ),
                    }
                    match expected_value {
                        Some(expected_value) => {
                            let value = find_section_text(clip, TextAnchor::End)
                                .unwrap_or_else(|| panic!("{file}: missing section {index} value"));
                            assert_text(
                                value,
                                expected_value,
                                &file,
                                &format!("section {index} value"),
                            );
                        }
                        None => assert!(
                            find_section_text(clip, TextAnchor::End).is_none(),
                            "{file}: unexpected section {index} value"
                        ),
                    }
                }
                None => assert!(
                    expected_label.is_none() && expected_value.is_none(),
                    "{file}: missing section {index} clip"
                ),
            }
        }

        let actual_leaves: Vec<&Group> = container
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Group(group)
                    if group
                        .class
                        .as_deref()
                        .is_some_and(|class| class.starts_with("treemapNode")) =>
                {
                    Some(group)
                }
                _ => None,
            })
            .collect();
        let expected_leaves = expected["leaves"].as_array().expect("leaves");
        assert_eq!(
            actual_leaves.len(),
            expected_leaves.len(),
            "{file}: leaf count"
        );

        for (index, (actual, expected)) in actual_leaves.iter().zip(expected_leaves).enumerate() {
            close(
                actual.transform.e,
                number(&expected["transform"], "x", &file),
                &format!("leaf {index} x"),
                &file,
            );
            close(
                actual.transform.f,
                number(&expected["transform"], "y", &file),
                &format!("leaf {index} y"),
                &file,
            );
            let leaf_rect = rect(&actual.items[0], &file, "leaf rect");
            assert_rect(
                leaf_rect,
                &expected["rect"],
                &file,
                &format!("leaf {index} rect"),
            );

            let clip = actual.items.iter().find_map(|item| match item {
                Item::Group(group) => Some(group),
                _ => None,
            });
            let expected_label = expected_text(&expected["label"]);
            let expected_value = expected_text(&expected["value"]);
            match clip {
                Some(clip) => {
                    match expected_label {
                        Some(expected_label) => {
                            let label = find_text(clip, TextBaseline::Middle)
                                .unwrap_or_else(|| panic!("{file}: missing leaf {index} label"));
                            assert_text(
                                label,
                                expected_label,
                                &file,
                                &format!("leaf {index} label"),
                            );
                        }
                        None => assert!(
                            find_text(clip, TextBaseline::Middle).is_none(),
                            "{file}: unexpected leaf {index} label"
                        ),
                    }
                    match expected_value {
                        Some(expected_value) => {
                            let value = find_text(clip, TextBaseline::Hanging)
                                .unwrap_or_else(|| panic!("{file}: missing leaf {index} value"));
                            assert_text(
                                value,
                                expected_value,
                                &file,
                                &format!("leaf {index} value"),
                            );
                        }
                        None => assert!(
                            find_text(clip, TextBaseline::Hanging).is_none(),
                            "{file}: unexpected leaf {index} value"
                        ),
                    }
                }
                None => assert!(
                    expected_label.is_none() && expected_value.is_none(),
                    "{file}: missing leaf {index} clip"
                ),
            }
        }
    }
}

#[test]
fn formats_values_like_d3() {
    let cases: &[(&str, f64, &str)] = &[
        (",", 1234.0, "1,234"),
        (",", 1234567.0, "1,234,567"),
        (",", 1234.5, "1,234.5"),
        (",", 0.0, "0"),
        ("$0,0", 1060000.0, "$1,060,000"),
        ("$.2f", 1234.567, "$1234.57"),
        ("$,.2", 1234.567, "$1.2e+3"),
        ("", 1234567.0, "1,234,567"),
    ];
    for &(specifier, value, expected) in cases {
        let format = ValueFormat::from_config(specifier);
        assert_eq!(format.render(value), expected, "{specifier} {value}");
    }
}

#[test]
fn draws_shapes_and_text_from_the_theme() {
    let config = Config::default();
    let scene = render(
        "treemap title Shares\n  \"Alpha\"\n    \"One\": 60\n    \"Two\": 40\n",
        &config,
    )
    .expect("render treemap");
    let theme = &config.theme_variables;
    let theme_value = |key: &str| theme[key].as_str().expect("theme string").to_string();

    let container = scene
        .items
        .iter()
        .find_map(|item| match item {
            Item::Group(group) if group.class.as_deref() == Some("treemapContainer") => Some(group),
            _ => None,
        })
        .expect("container");
    let section = container
        .items
        .iter()
        .find_map(|item| match item {
            Item::Group(group) if group.class.as_deref() == Some("treemapSection") => Some(group),
            _ => None,
        })
        .expect("section");
    let body = rect(&section.items[1], "scene", "section body");
    assert_eq!(
        color_of(&body.style.fill),
        Some(theme_value("cScale0").as_str())
    );
    assert_eq!(
        color_of(&body.style.stroke),
        Some(theme_value("cScalePeer0").as_str())
    );

    let clip = group(&section.items[2], "scene", "section clip");
    let label = find_section_text(clip, TextAnchor::Start).expect("section label");
    assert_eq!(
        color_of(&label.fill),
        Some(theme_value("cScaleLabel0").as_str())
    );
    assert_eq!(label.font.size, SECTION_LABEL_FONT_SIZE);
    assert_eq!(label.font.weight, 700);

    let leaves: Vec<&Group> = container
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Group(group)
                if group
                    .class
                    .as_deref()
                    .is_some_and(|class| class.starts_with("treemapNode")) =>
            {
                Some(group)
            }
            _ => None,
        })
        .collect();
    assert_eq!(leaves.len(), 2);
    let leaf_rect = rect(&leaves[0].items[0], "scene", "leaf rect");
    assert_eq!(
        color_of(&leaf_rect.style.fill),
        Some(theme_value("cScale0").as_str())
    );

    let title = match &scene.items[0] {
        Item::Text(title) => title,
        _ => panic!("title is not text"),
    };
    assert_eq!(title.font.size, TITLE_FONT_SIZE);
    assert_eq!(
        color_of(&title.fill),
        Some(theme_value("titleColor").as_str())
    );
}

#[test]
fn render_diagram_dispatches_treemap() {
    let scene = crate::render_diagram(
        "treemap title Dispatch\n  \"Alpha\"\n    \"One\": 1\n",
        &Config::default(),
    )
    .expect("render treemap through render_diagram");
    assert!(scene.view_box.width > 0.0);
    assert!(scene.view_box.height > 0.0);
    assert!(
        scene
            .items
            .iter()
            .any(|item| matches!(item, Item::Group(_)))
    );
}

#[test]
fn rejects_a_body_without_a_treemap_header() {
    assert!(render("graph TD\n  A --> B\n", &Config::default()).is_err());
}
